const Map<String, Map<String, String>> dashaBhuktiPhalasMlExpanded = {
  'ರವಿ': {
    'ರವಿ': 'രവി മഹാദശയിൽ രവി ഭുക്തി അധികാരം, സർക്കാർ അനുകൂല്യം, നേതൃത്വ ഗുണം എന്നിവ നൽകുന്നു. ജോലിയിൽ ഉയർച്ച, മേലധികാരികളുടെ അംഗീകാരം ലഭിക്കും. തലവേദന, പനി, പിത്ത ദോഷം, കണ്ണ് സംബന്ധ പ്രശ്നങ്ങൾ ഉണ്ടാകാം. അച്ഛനുമായി നല്ല ബന്ധം, പക്ഷേ അഹങ്കാരം കൂടാം.',
    'ಚಂದ್ರ': 'രവി-ചന്ദ്ര ഭുക്തിയിൽ ശത്രുനാശം, മനസ്സമാധാനം, കീർത്തി എന്നിവ ലഭിക്കും. അമ്മയിൽ നിന്നോ സ്ത്രീകളിൽ നിന്നോ ലാഭം, വസ്ത്ര-ആഭരണ പ്രാപ്തി, ഗൃഹ സുഖം ഉണ്ടാകും. ആരോഗ്യം പൊതുവേ നല്ലതാണ്, പക്ഷേ ശീത-കഫ ദോഷം വരാം. കുടുംബത്തിൽ ശാന്തിയും സമരസവും നിലനിൽക്കും.',
    'ಕುಜ': 'രവി-കുജ ഭുക്തിയിൽ ധൈര്യവും പരാക്രമവും വർദ്ധിക്കുന്നു. രോഗ-വ്യാജ്യ നിർമൂലനം, അധികാര ലാഭം, മത്സരങ്ങളിൽ വിജയം ലഭിക്കും. പക്ഷേ ഉഷ്ണ രോഗം, രക്ത സംബന്ധ പ്രശ്നം, അപകട ഭയം ഉണ്ട്. സഹോദരങ്ങളുമായി മിശ്ര ബന്ധം, ഭൂമി-വാഹന ലാഭം സാധ്യം.',
    'ರಾಹು': 'രവി-രാഹു ഭുക്തിയിൽ ഗ്രഹണ ദോഷം പോലുള്ള അനുഭവം ഉണ്ടാകുന്നു. സർക്കാരിൽ നിന്നോ മേലധികാരികളിൽ നിന്നോ ഭയം, സ്ഥാനചലനം, മാനസിക ആശയക്കുഴപ്പം. അപ്രതീക്ഷിത ആരോഗ്യ പ്രശ്നം, വിഷ ഭയം ഉണ്ട്. കുടുംബത്തിൽ അശാന്തി, അച്ഛന് കഷ്ടം, അപകീർത്തി സാധ്യം.',
    'ಗುರು': 'രവി-ഗുരു ഭുക്തിയിൽ ദൈവാനുഗ്രഹം, ധർമ കാര്യങ്ങളിൽ പുരോഗതി, ഗുരു കൃപ ലഭിക്കും. വിദ്യാ-ജ്ഞാന ലാഭം, സർക്കാർ ബഹുമാനം, സാമൂഹിക പദവി ഉയരും. ആരോഗ്യം പൊതുവേ നല്ലത്, പിത്ത ദോഷം ചെറുതായി ഉണ്ടാകാം. സന്താന സുഖം, അച്ഛന്റെ അനുഗ്രഹം, ആത്മീയ വളർച്ച.',
